// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(caller != newOwner);

        // Record owner before the call
        address prevOwner = c.owner();

        // Call setOwner as the fuzzed caller
        vm.startPrank(caller);
        bool result = c.setOwner(newOwner);
        vm.stopPrank();

        // Compute expected:
        // Only the previous owner should succeed and actually change owner.
        bool expectedSuccess = (caller == prevOwner);
        address expectedOwner = expectedSuccess ? newOwner : prevOwner;

        // General invariant:
        // After any call, success equals (caller == previous owner),
        // and the new owner equals newOwner if success else previous owner.
        assertTrue(result == expectedSuccess && c.owner() == expectedOwner);
    }
}

